#include <iostream>
#include <memory>

class Widget {
public:
    Widget() { std::cout << "Widget constructed" << std::endl; }
    ~Widget() { std::cout << "Widget destroyed" << std::endl; }
    void do_something() { std::cout << "Doing something" << std::endl; }
};

int main() {
    // Using std::unique_ptr for exclusive ownership
    auto widgetPtr = std::make_unique<Widget>();
    widgetPtr->do_something();

    // Using std::shared_ptr for shared ownership
    std::shared_ptr<Widget> sharedWidget1 = std::make_shared<Widget>();
    std::shared_ptr<Widget> sharedWidget2 = sharedWidget1; // shared ownership
    sharedWidget1->do_something();
    sharedWidget2->do_something();
    // Widgets are automatically destroyed when last shared_ptr goes out of scope
    return 0;
}
